UPDATE lab_media_object SET status='DELETED',ready_dedup_slot=NULL,ready_primary_slot=NULL,
    version=version+1,deleted_by=#{actorId},deleted_at=#{now}
WHERE id=#{mediaId} AND version=#{version} AND status='READY'

UPDATE lab_procurement_attachment SET status='DELETED',version=version+1,
    deleted_by=#{actorId},deleted_at=#{now}
WHERE id=#{id} AND version=#{version} AND status='READY'
